function buildWeightedGraphImpl(n, edges, directed = true) {
  const adj = Array.from({length: n}, () => []);
  for (const [u, v, w] of edges) {
    adj[u].push([v, w]);
    if (!directed) adj[v].push([u, w]);
  }
  return adj;
}

function selectAlgorithm(props) {
  const {weighted, negativeWeights, kHopConstraint, allPairs} = props;
  if (allPairs) return 'Floyd-Warshall O(V^3)';
  if (!weighted) return 'BFS O(V+E)';
  if (negativeWeights && kHopConstraint) return 'Bellman-Ford K+1 rounds + prevDist copy';
  if (negativeWeights) return 'Bellman-Ford V-1 rounds';
  return "Dijkstra's O((V+E) log V) with lazy deletion";
}

