function bellmanFordImpl(n, edges, source) {
  const dist = new Array(n).fill(Infinity);
  dist[source] = 0;
  for (let r = 0; r < n-1; r++) {
    let updated = false;
    for (const [u, v, w] of edges) {
      if (dist[u] !== Infinity && dist[u]+w < dist[v]) {
        dist[v] = dist[u]+w;
        updated = true;
      }
    }
    if (!updated) break;
  }
  for (const [u, v, w] of edges)
    if (dist[u] !== Infinity && dist[u]+w < dist[v]) return null;
  return dist;
}

