function findCheapestPriceImpl(n, flights, src, dst, k) {
  const dist = new Array(n).fill(Infinity);
  dist[src] = 0;
  for (let round = 0; round <= k; round++) {
    const prev = [...dist];
    for (const [u, v, price] of flights) {
      if (prev[u] !== Infinity && prev[u] + price < dist[v])
        dist[v] = prev[u] + price;
    }
  }
  return dist[dst] === Infinity ? -1 : dist[dst];
}

