function classifyShortestPath(props) {
  const {weighted, negativeWeights, kHopConstraint, allPairs} = props;
  if (allPairs) return 'Floyd-Warshall O(V^3)';
  if (!weighted) return 'BFS O(V+E)';
  if (negativeWeights && kHopConstraint) return 'Bellman-Ford K+1 rounds + prevDist copy';
  if (negativeWeights) return 'Bellman-Ford V-1 rounds';
  return "Dijkstra's O((V+E) log V) with lazy deletion";
}

function module7Summary() {
  const vals = Object.values(MODULE7_PROBLEMS);
  return {
    total: vals.length,
    dijkstra: vals.filter(p => p.algorithm.includes('Dijkstra')).length,
    bellmanFord: vals.filter(p => p.algorithm.includes('Bellman')).length
  };
}

function requiresPrevDistCopy(algorithm) {
  return algorithm === 'Bellman-Ford K+1';
